import{_ as e,o as a,c as i,a3 as l}from"./chunks/framework.CJlOecQn.js";const u=JSON.parse('{"title":"العيش في قطر","titleTemplate":"دليل موثّق للمقيمين","description":"","frontmatter":{"layout":"home","title":"العيش في قطر","titleTemplate":"دليل موثّق للمقيمين","hero":{"name":"العيش في قطر","text":"دليل عملي لكل معلومة فيه مصدر رسمي","tagline":"التأشيرات والبطاقة الشخصية والصحة والسكن والعمل والمال والحياة اليومية. كل معلومة مربوطة بالصفحة الرسمية التي جاءت منها، مع الشهر الذي تحققنا فيه منها. مجاني، بالعربية والإنجليزية، ومفتوح للتصحيح.","image":{"src":"/favicon.svg","alt":""},"actions":[{"theme":"brand","text":"ابدأ القراءة","link":"/ar/guide/"},{"theme":"alt","text":"قائمة أول 30 يومًا","link":"/ar/checklist"},{"theme":"alt","text":"English","link":"/"}]},"features":[{"title":"وصلت حديثًا","details":"تأشيرات الدخول، ورخصة الإقامة والبطاقة الشخصية، وتطبيق مطراش.","link":"/ar/guide/residence-permit-and-qid","linkText":"رخصة الإقامة والبطاقة الشخصية"},{"title":"تعمل أو تبحث عن عمل","details":"العقود والأجور والإجازات ومكافأة نهاية الخدمة وتغيير صاحب العمل.","link":"/ar/guide/work-and-labour-rights","linkText":"العمل وحقوق العمال"},{"title":"ستستقدم عائلتك","details":"إقامة العائلة وتأشيرات الزيارة، واختيار مدرسة لأطفالك.","link":"/ar/guide/family-visas","linkText":"التأشيرات العائلية"},{"title":"تستأجر سكنًا","details":"عقود الإيجار وفض المنازعات، وتوصيل الكهرباء والماء.","link":"/ar/guide/housing-and-utilities","linkText":"السكن والإيجار"}]},"headers":[],"relativePath":"ar/index.md","filePath":"ar/index.md"}'),n={name:"ar/index.md"};function r(s,t,o,d,c,p){return a(),i("div",null,[...t[0]||(t[0]=[l('<h2 id="لماذا-هذا-الدليل" tabindex="-1">لماذا هذا الدليل <a class="header-anchor" href="#لماذا-هذا-الدليل" aria-label="Permalink to &quot;لماذا هذا الدليل&quot;">​</a></h2><p>معظم النصائح التي يتداولها المقيمون الجدد موجودة في المنتديات ومجموعات المحادثة والمدونات. بعضها مفيد، وكثير منها قديم، ونادرًا ما يذكر من أين جاءت المعلومة. والصفحات الرسمية موجودة لكل شيء تقريبًا، لكنها موزعة على وزارات ومواقع كثيرة.</p><p>يجمع هذا الدليل الخطوات العملية في مكان واحد، ويربط كل معلومة بالصفحة الرسمية التي جاءت منها، لتتأكد منها بنفسك قبل أن تتصرف.</p><h2 id="كيف-يعمل" tabindex="-1">كيف يعمل <a class="header-anchor" href="#كيف-يعمل" aria-label="Permalink to &quot;كيف يعمل&quot;">​</a></h2><ul><li><strong>حاشية لكل معلومة.</strong> كل فقرة تشير إلى الصفحة الرسمية بعينها، مع الشهر الذي تحققنا فيه منها آخر مرة.</li><li><strong>لغتان ومصادر واحدة.</strong> الصفحات العربية والإنجليزية تستشهد بالمصادر نفسها، وهناك فحص آلي يفشل إذا اختلفتا.</li><li><strong>فحص آلي.</strong> أداة تزور كل رابط من روابط المصادر وتنبّه إذا اختفت صفحة أو نُقلت أو تغيّرت. والمواقع التي ترفض الزوار الآليين تُدرج في قائمة ليفتحها شخص في المتصفح.</li><li><strong>مفتوح للتصحيح.</strong> في كل صفحة رابط للتعديل. إذا وجدت معلومة قديمة فأرسل التصحيح مع رابط الصفحة الرسمية التي تبيّن المعلومة الصحيحة.</li></ul><p>اقرأ <a href="./sourcing">كيف نوثّق المعلومات</a> أو اطّلع على <a href="./help-wanted">المواضيع التي نحتاج فيها إلى مساعدتك</a>.</p><div class="warning custom-block"><p class="custom-block-title">ليس استشارة قانونية</p><p>هذا دليل مجتمعي وليس خدمة حكومية. الأنظمة والرسوم والإجراءات تتغير، فتأكد دائمًا من الصفحة الرسمية المذكورة في المصادر قبل أن تتخذ أي خطوة.</p></div>',7)])])}const m=e(n,[["render",r]]);export{u as __pageData,m as default};
